#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int MAXV = 100000;
    vector<long long> cnt(MAXV + 1, 0);

    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        ++cnt[x];
    }

    vector<long long> dp(MAXV + 1, 0);

    dp[1] = cnt[1];

    for (int x = 2; x <= MAXV; ++x) {
        dp[x] = max(dp[x - 1], dp[x - 2] + 1LL * x * cnt[x]);
    }

    cout << dp[MAXV] << '\n';
    return 0;
}

