int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    vector<int> tails;

    for (int value : a) {
        auto it = lower_bound(tails.begin(), tails.end(), value);

        if (it == tails.end()) {
            tails.push_back(value);
        } else {
            *it = value;
        }
    }

    cout << tails.size() << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = s.size();
    int m = t.size();

    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (s[i - 1] == t[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    cout << dp[n][m] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t;
    cin >> s >> t;

    int n = s.size();
    int m = t.size();

    vector<int> dp(m + 1, 0);

    for (int i = 1; i <= n; ++i) {
        int diagonal = 0;

        for (int j = 1; j <= m; ++j) {
            int old = dp[j];

            if (s[i - 1] == t[j - 1]) {
                dp[j] = diagonal + 1;
            } else {
                dp[j] = max(dp[j], dp[j - 1]);
            }

            diagonal = old;
        }
    }

    cout << dp[m] << '\n';
    return 0;
}
